62	  dateFormat: z.enum(["iso", "dmy", "mdy"]),
63	  amountSign: z.enum(["signed", "outflow-positive"]),
64	  numericConvention: z.enum(["decimal-dot", "decimal-comma"]).optional(),
65	  parserVersion: z.literal("numeric-convention-v2").optional(),
66	  rowContractVersion: z.literal("normalized-row-v1").optional(),
67	  workbookScope: workbookScopeSchema.optional(),
68	  rowDecisions: z.array(z.discriminatedUnion("action", [
69	    z.object({ rowNumber: z.number().int().min(2), action: z.literal("correct"),
70	      values: z.record(z.string(), z.string().max(100_000)).refine(value => Object.keys(value).length > 0, "Correction needs source values") }).strict(),
71	    z.object({ rowNumber: z.number().int().min(2), action: z.literal("exclude"), reason: z.string().trim().min(1).max(500) }).strict(),
72	  ])).max(100_000).optional(),
73	}).strict().refine(
74	  (m) => m.amountColumn ? !m.debitColumn && !m.creditColumn : Boolean(m.debitColumn && m.creditColumn),
75	  "Choose either one amount column or both debit and credit columns",
76	);
