97	const knownStatements: { format: string; headers: string[]; mapping: Omit<ImportMapping, "accountName" | "currencyCode">; routeName: (route: Omit<AccountRoute, "accountName">) => string }[] = [
98	  { format: "Revolut", headers: ["Type", "Product", "Started Date", "Completed Date", "Description", "Amount", "Fee", "Currency", "State", "Balance"],
99	    mapping: { amountColumn: "Amount", currencyColumn: "Currency", amountSign: "signed", dateColumn: "Completed Date", descriptionColumn: "Description", dateFormat: "iso",
100	      productColumn: "Product", statusColumn: "State", balanceColumn: "Balance", typeColumn: "Type", feeColumn: "Fee" },
101	    routeName: route => ["Revolut", route.productValue].filter(Boolean).join(" ") },
102	  { format: "IBAN bank export", headers: ["Booking date", "Value date", "Transaction type", "Booking text", "Amount", "Currency", "Account IBAN", "Category", "Sender", "Recipient", "Transfer purpose"],
103	    mapping: { amountColumn: "Amount", currencyColumn: "Currency", amountSign: "signed", dateColumn: "Booking date", descriptionColumn: "Booking text", dateFormat: "dmy",
104	      categoryColumn: "Category", typeColumn: "Transaction type", accountColumn: "Account IBAN" },
105	    routeName: route => route.accountValue ? `Account ${maskAccountNumber(route.accountValue)}` : "Bank account" },
106	];
