134	export function validateImportConfirmation(rows: SourceRow[], input: unknown): ImportMapping {
135	  const mapping = validateMapping(input, rows);
136	  if (!mapping.numericConvention) throw new Error("Review and select the source numeric convention before importing");
137	  const naive = reviewedSourceRows(rows, mapping).some(row => row && /[ T]\d{2}:\d{2}:\d{2}(?:\.\d{1,3})?$/.test(row[mapping.dateColumn]?.trim() ?? ""));
138	  if (naive && (!mapping.timestampTimezone || !mapping.timestampTimezoneConfirmed))
139	    throw new Error("Review and confirm the source timestamp timezone before importing");
140	  mapRows(rows, mapping);
141	  return { ...mapping, parserVersion: "numeric-convention-v2", rowContractVersion: "normalized-row-v1" };
142	}
