151	export function parseCsv(text: string): SourceRow[] {
152	  assertStorageCompatible(text);
153	  const result = Papa.parse<SourceRow>(text.replace(/^\uFEFF/, ""), {
154	    header: true,
155	    skipEmptyLines: "greedy",
156	  });
157	  if (Object.keys(result.meta.renamedHeaders ?? {}).length || new Set(result.meta.fields).size !== result.meta.fields?.length)
158	    throw new Error("Duplicate CSV headers");
159	  const headers = result.meta.fields ?? [];
160	  if (headers.some(header => header.startsWith("__moneo_csv_") || header === "__parsed_extra")) throw new Error("Reserved CSV evidence header");
161	  const fatal = result.errors.find(error => error.type !== "FieldMismatch" || !["TooFewFields", "TooManyFields"].includes(error.code)
162	    || !Number.isInteger(error.row) || error.row! < 0 || error.row! >= result.data.length);
163	  if (fatal) throw new Error(`CSV parse error: ${fatal.message}`);
164	  const issues = new Map(result.errors.map(error => [error.row!, error.code]));
165	  return result.data.map((row, index) => {
166	    const extra = (row as unknown as { __parsed_extra?: string[] }).__parsed_extra;
167	    return { ...Object.fromEntries(headers.map(header => [header, row[header] ?? ""])),
168	      ...(issues.has(index) ? { [csvIssueColumn]: issues.get(index)!,
169	        __moneo_csv_field_count: String(headers.filter(header => Object.hasOwn(row, header)).length + (extra?.length ?? 0)) } : {}),
170	      ...(extra?.length ? { [csvExtraColumn]: JSON.stringify(extra) } : {}) };
171	  });
172	}
