321	export function parseAmountMinor(input: string, currencyCode: string = "EUR", convention?: ImportMapping["numericConvention"]): bigint {
322	  const digits = minorDigits(currencyCode);
323	  let value = input.trim().replace(/\s/g, "").replace(/[€$£]/g, "");
324	  if (!/^(?:\(\d[\d.,]*\)|[-+]?\d[\d.,]*|\d[\d.,]*-)$/.test(value)) throw new Error(`Invalid amount: ${input}`);
325	  const negative = /^\(.*\)$/.test(value) || value.startsWith("-") || value.endsWith("-");
326	  value = value.replace(/[()\-+]/g, "");
327	  const comma = value.lastIndexOf(",");
328	  const dot = value.lastIndexOf(".");
329	  if (!convention && (comma < 0 || dot < 0) && /^\d{1,3}([.,]\d{3})+$/.test(value))
330	    throw new Error("Review the source numeric convention: separator could represent decimals or grouping");
331	  const decimal = convention ? (convention === "decimal-dot" ? "." : ",") : comma > dot ? "," : ".";
332	  const grouping = decimal === "." ? "," : ".";
333	  const parts = value.split(decimal);
334	  const wholePattern = grouping === "," ? /^(\d{1,3}(,\d{3})+|\d+)$/ : /^(\d{1,3}(\.\d{3})+|\d+)$/;
335	  if (parts.length > 2 || !wholePattern.test(parts[0]) ||
336	      (parts[1] !== undefined && (!/^\d+$/.test(parts[1]) || parts[1].length > digits))) {
337	    throw new Error(`Invalid amount: ${input}`);
338	  }
339	  const whole = parts[0].replace(/[.,]/g, "");
340	  const fraction = (parts[1] ?? "").padEnd(digits, "0").slice(0, digits);
341	  const minor = BigInt(whole) * pow10(digits) + BigInt(fraction || "0");
342	  return databaseMinor(negative ? -minor : minor);
343	}
344	
345	function pow10(exponent: number): bigint {
346	  return 10n ** BigInt(exponent);
347	}
