cat > scripts/.diag.tmp.mjs <<'EOF'
import postgres from "postgres";
import { readFileSync } from "node:fs";
const { id } = JSON.parse(readFileSync(".qa/e2e-auth-user.json", "utf8"));
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
try {
  await db.begin(async tx => {
    for (let i = 0; i < 40; i++) {
      try {
        await tx`savepoint s`;
        await tx`delete from public.workspaces where owner_id=${id}`;
        await tx`delete from auth.users where id=${id}`;
        console.log("deleted after", i, "blocking tables"); return;
      } catch (e) {
        await tx`rollback to savepoint s`;
        const m = /on table "(\w+)"/g; const tables = [...e.message.matchAll(m)].map(x => x[1]);
        const blocker = tables.at(-1);
        if (!blocker || !e.detail?.includes("still referenced")) throw e;
        const cols = await tx`select column_name from information_schema.columns where table_schema='public' and table_name=${blocker} and column_name in ('workspace_id','actor_id','user_id','owner_id')`;
        if (!cols.length) throw e;
        for (const { column_name } of cols)
          await tx.unsafe(`delete from public."${blocker}" where "${column_name}" = $1 or ("${column_name}" in (select id from public.workspaces where owner_id=$1))`, [id]);
        console.log("cleared", blocker);
      }
    }
    throw new Error("gave up");
  });
} catch (e) { console.log("ROLLED BACK:", e.message); }
await db.end();
EOF
node --env-file=.env scripts/.diag.tmp.mjs; rm scripts/.diag.tmp.mjs

