import { chromium } from "@playwright/test";
import postgres from "postgres";
import { randomUUID } from "node:crypto";
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
const [{ id: ws }] = await db`select w.id from public.workspaces w join auth.users u on u.id=w.owner_id where u.email=${process.env.E2E_USER_EMAIL}`;
const done = randomUUID(), job = randomUUID();
await db`insert into public.background_jobs(id,workspace_id,kind,status,stage) values(${done},${ws},'financial_review','completed','completed')`;
await db`insert into public.saved_analyses(workspace_id,job_id,title,body,evidence) values(${ws},${done},'Done','Body','{}')`;
await db`insert into public.background_jobs(id,workspace_id,kind,status,stage,workflow_run_id,dispatched_at) values(${job},${ws},'financial_review','running','writing_review',${"wrun_dbg_" + job},now())`;
const b = await chromium.launch(); const p = await b.newPage({ storageState: "e2e/.auth.json", baseURL: "http://localhost:3000" });
p.on("framenavigated", f => { if (f === p.mainFrame()) console.log("NAV", f.url()); });
await p.goto("/ai");
await p.getByText("Run a deep review", { exact: true }).click();
await p.getByLabel("Saved reviews").selectOption(job);
await p.getByRole("button", { name: "Stop", exact: true }).click();
await p.waitForTimeout(3000);
console.log("details open:", await p.locator("details", { hasText: "Run a deep review" }).last().evaluate(d => d.open));
console.log("status:", await p.locator('p[role="status"]').allTextContents());
await b.close();
await db`delete from public.saved_analyses where job_id in (${done},${job})`; await db`delete from public.background_jobs where id in (${done},${job})`;
await db.end();
EOF
node --env-file=.env scripts/.dbg.tmp.mjs 2>&1 | tail -8; rm scripts/.dbg.tmp.mjs

